import{_ as a,o as r,c as t,a2 as h}from"./chunks/framework.CHeM0PsO.js";const w=JSON.parse('{"title":"Research","description":"","frontmatter":{},"headers":[],"relativePath":"skill/research.md","filePath":"skill/research.md","lastUpdated":null}'),i={name:"skill/research.md"};function o(n,e,l,s,p,c){return r(),t("div",null,[...e[0]||(e[0]=[h('<h1 id="research" tabindex="-1">Research <a class="header-anchor" href="#research" aria-label="Permalink to &quot;Research&quot;">​</a></h1><h2 id="工具" tabindex="-1">工具 <a class="header-anchor" href="#工具" aria-label="Permalink to &quot;工具&quot;">​</a></h2><p>谷歌学术、MIT/卡梅隆/北大清华图书馆资源库、公司内部知识库(如商汤/阿里)</p><h2 id="博客" tabindex="-1">博客 <a class="header-anchor" href="#博客" aria-label="Permalink to &quot;博客&quot;">​</a></h2><ul><li><a href="https://medium.com/" target="_blank" rel="noreferrer">https://medium.com/</a></li><li><a href="https://towardsdatascience.com/" target="_blank" rel="noreferrer">https://towardsdatascience.com/</a></li><li><a href="https://ai.googleblog.com/" target="_blank" rel="noreferrer">https://ai.googleblog.com/</a></li><li><a href="https://deepmind.com/blog/?category=research" target="_blank" rel="noreferrer">https://deepmind.com/blog/?category=research</a></li></ul><h2 id="论文" tabindex="-1">论文 <a class="header-anchor" href="#论文" aria-label="Permalink to &quot;论文&quot;">​</a></h2><h3 id="顶级会议" tabindex="-1">顶级会议 <a class="header-anchor" href="#顶级会议" aria-label="Permalink to &quot;顶级会议&quot;">​</a></h3><ul><li>NLP：ACL / NAACL / EMNLP ...</li><li>CV: CVPR / ICCV / ECCV ...</li><li>ML: ICML / ICLR / NIPS / AAAI ...</li><li>Data Mining &amp; Information Retrieval: WWW / KDD / IJCAI ...</li></ul><h3 id="sci-hub" tabindex="-1">Sci-Hub <a class="header-anchor" href="#sci-hub" aria-label="Permalink to &quot;Sci-Hub&quot;">​</a></h3><p><a href="http://www.sci-hub.io/" target="_blank" rel="noreferrer">http://www.sci-hub.io/</a></p><p>备用站点：<a href="http://www.sci-hub.cc/" target="_blank" rel="noreferrer">http://www.sci-hub.cc/</a></p><p>中国版以及备用站点：<a href="http://www.sci-hub.cn/%E3%80%81http://www.sci-hub.xyz/" target="_blank" rel="noreferrer">http://www.sci-hub.cn/、http://www.sci-hub.xyz/</a></p><h3 id="谷歌学术" tabindex="-1">谷歌学术 <a class="header-anchor" href="#谷歌学术" aria-label="Permalink to &quot;谷歌学术&quot;">​</a></h3><p>谷歌学术网址，<a href="http://scholar.glgoo.org/%E3%80%81https://xs.glgoo.net/%E3%80%81http://scholar.hedasudi.com/" target="_blank" rel="noreferrer">http://scholar.glgoo.org/、https://xs.glgoo.net/、http://scholar.hedasudi.com/</a></p><p>也有镜像网站合集<a href="http://www.dirmor.com/" target="_blank" rel="noreferrer">http://www.dirmor.com/</a></p><h3 id="library-genesis" tabindex="-1">Library Genesis <a class="header-anchor" href="#library-genesis" aria-label="Permalink to &quot;Library Genesis&quot;">​</a></h3><p>Library Genesis号称是帮助全人类知识无版权传播的计划。网站上论文很多，下载方便，还有很多外文书籍和中文书籍，几乎每天都在更新。<a href="http://gen.lib.rus.ec/" target="_blank" rel="noreferrer">http://gen.lib.rus.ec/</a></p><h3 id="arxiv" tabindex="-1">arXiv <a class="header-anchor" href="#arxiv" aria-label="Permalink to &quot;arXiv&quot;">​</a></h3><p>www.arxiv.org</p><p>arXiv， 是archive（归档）的意思，是一个由康乃尔大学维护的免费的多学科论文预出版（preprint）数据库。所谓预出版，就是说论文还没有经过同行评审，文责自负，文章质量参差不齐，所以一般不会作为正式的学术成果。不过有的学科习惯上先把文章公开到arXiv上，然后再提交到会议上。 arXiv 是我们搜索、浏览和下载学术论文的重要工具。近 30 年来，arXiv 为公众和研究社区提供了开放获取学术论文的服务。这些论文涉及物理学的庞大分支和计算机科学的众多子学科，如数学、统计学、电气工程、定量生物学和经济学等等。</p><p>Chrome extension that adds video explanations to research papers on arxiv.org: <a href="https://github.com/amitness/papers-with-video" target="_blank" rel="noreferrer">https://github.com/amitness/papers-with-video</a></p><h3 id="arxiv-sanity" tabindex="-1">arxiv-sanity <a class="header-anchor" href="#arxiv-sanity" aria-label="Permalink to &quot;arxiv-sanity&quot;">​</a></h3><p><a href="http://www.arxiv-sanity.com/" target="_blank" rel="noreferrer">http://www.arxiv-sanity.com/</a></p><p>感兴趣相关度排序、个人图书馆、推荐系统、都在看什么<a href="https://cloud.tencent.com/developer/article/1473703" target="_blank" rel="noreferrer">2</a></p><p><a href="https://arxiv.xixiaoyao.cn/" target="_blank" rel="noreferrer">https://arxiv.xixiaoyao.cn/</a></p><h3 id="semanticscholar-3" tabindex="-1">semanticscholar[3] <a class="header-anchor" href="#semanticscholar-3" aria-label="Permalink to &quot;semanticscholar[3]&quot;">​</a></h3><p><a href="https://www.semanticscholar.org/" target="_blank" rel="noreferrer">https://www.semanticscholar.org/</a></p><h3 id="metacademy" tabindex="-1">metacademy <a class="header-anchor" href="#metacademy" aria-label="Permalink to &quot;metacademy&quot;">​</a></h3><p><a href="https://metacademy.org/" target="_blank" rel="noreferrer">https://metacademy.org/</a></p><p>metacademy看作一副机器学习和人工智能的知识图谱，在上面搜索任意机器学习或者人工智能的知识概念，它会告诉你学习这个知识点需要什么前置知识，需要多长时间掌握，并罗列出相关的课程。</p><h3 id="aminer-3" tabindex="-1">AMiner[3] <a class="header-anchor" href="#aminer-3" aria-label="Permalink to &quot;AMiner[3]&quot;">​</a></h3><p>输入关键词就能找到对应的学者： <a href="https://www.aminer.cn/" target="_blank" rel="noreferrer">https://www.aminer.cn/</a></p><p><a href="https://www.aminer.cn/ai2000/country/China" target="_blank" rel="noreferrer">https://www.aminer.cn/ai2000/country/China</a></p><h3 id="论文-1" tabindex="-1">论文 <a class="header-anchor" href="#论文-1" aria-label="Permalink to &quot;论文&quot;">​</a></h3><p><a href="https://openreview.net/" target="_blank" rel="noreferrer">https://openreview.net/</a></p><p>CV领域Paper论文常见单词(一) - 王大东的文章 - 知乎 <a href="https://zhuanlan.zhihu.com/p/58860096" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/58860096</a></p><p><a href="https://ying-zhang.github.io/misc/2016/we-love-paper/" target="_blank" rel="noreferrer">https://ying-zhang.github.io/misc/2016/we-love-paper/</a></p><h2 id="代码" tabindex="-1">代码 <a class="header-anchor" href="#代码" aria-label="Permalink to &quot;代码&quot;">​</a></h2><h3 id="papers-with-code1" tabindex="-1">Papers with Code<a href="https://www.jiqizhixin.com/articles/2020-10-09-5" target="_blank" rel="noreferrer">1</a> <a class="header-anchor" href="#papers-with-code1" aria-label="Permalink to &quot;Papers with Code[1]&quot;">​</a></h3><p>机器学习资源网站 Papers with Code 自创立以来，凭借丰富的开放资源和卓越的社区服务，成为机器学习研究者最常用的资源网站之一。网站还根据细分领域的指标对论文进行了整理和排序。以图像配准（Image Registration）为例。指标、论文、代码，安排得明明白白。</p><p>2019 年底，Papers with Code 正式并入 Facebook AI。最近，它又有了新举措：与论文预印本平台 arXiv 展开合作，支持在 arXiv 页面上添加代码链接。</p><p>Browse State-of-the-Art: <a href="https://paperswithcode.com/sota" target="_blank" rel="noreferrer">https://paperswithcode.com/sota</a></p><h3 id="github-awesome-3" tabindex="-1">Github - Awesome[3] <a class="header-anchor" href="#github-awesome-3" aria-label="Permalink to &quot;Github - Awesome[3]&quot;">​</a></h3><p>以 awesome 为名，进行某个领域资料的高质量整合。</p><h3 id="实践" tabindex="-1">实践 <a class="header-anchor" href="#实践" aria-label="Permalink to &quot;实践&quot;">​</a></h3><p>推荐网站：<a href="https://www.kaggle.com/" target="_blank" rel="noreferrer">https://www.kaggle.com/</a></p><h2 id="mathpix" tabindex="-1">mathpix <a class="header-anchor" href="#mathpix" aria-label="Permalink to &quot;mathpix&quot;">​</a></h2><p>手写/截图 转 LaTex公式：<a href="https://mathpix.com/" target="_blank" rel="noreferrer">https://mathpix.com/</a></p><p>LaTex如果所有公式都要自己手打还是很痛苦的。（虽然很多时候一篇Deep Learning方向的paper公式数量只有十个左右（这还是在强行加上LSTM等被翻来覆去写烂的公式的情况下））</p><p><a href="http://deepdive.nn.157239n.com/" target="_blank" rel="noreferrer">http://deepdive.nn.157239n.com/</a></p><h2 id="报告" tabindex="-1">报告 <a class="header-anchor" href="#报告" aria-label="Permalink to &quot;报告&quot;">​</a></h2><p><a href="http://www.zft-park.com.cn/index.php?m=Article&amp;a=show&amp;id=384" target="_blank" rel="noreferrer">http://www.zft-park.com.cn/index.php?m=Article&amp;a=show&amp;id=384</a></p><p>[3]: 有哪些可以自学机器学习、深度学习、人工智能的网站？ - 白小鱼的回答 - 知乎 <a href="https://www.zhihu.com/question/375537442/answer/1356785270" target="_blank" rel="noreferrer">https://www.zhihu.com/question/375537442/answer/1356785270</a> [4]: 有哪些可以自学机器学习、深度学习、人工智能的网站？ - 鑫鑫淼淼焱焱的回答 - 知乎 <a href="https://www.zhihu.com/question/375537442/answer/1426414603" target="_blank" rel="noreferrer">https://www.zhihu.com/question/375537442/answer/1426414603</a> [5]: 百度学术能否替代 Google 学术网站？有没有其他选择？ - 答答的回答 - 知乎 <a href="https://www.zhihu.com/question/24143504/answer/280410393" target="_blank" rel="noreferrer">https://www.zhihu.com/question/24143504/answer/280410393</a></p>',53)])])}const d=a(i,[["render",o]]);export{w as __pageData,d as default};
